# owner: platform
"""Absence notices written for parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

def _check_student(
    student: Student, marks: List[Mark]
) -> None:
    seen = {mark.student_id for mark in marks}
    strays = sorted(seen - {student.student_id})
    if strays:
        raise ValueError(f"marks for other ids: {strays}")

def _absent_days(
    student: Student, marks: List[Mark]
) -> List[date]:
    _check_student(student, marks)
    days = days_missed(marks)
    if not days:
        raise ValueError("no absences to report")
    return days

def _long_date(day: date) -> str:
    return f"{day:%B} {day.day}, {day.year}"

def _join_dates(days: List[date]) -> str:
    names = [_long_date(day) for day in days]
    if len(names) == 1:
        return names[0]
    head = ", ".join(names[:-1])
    return f"{head} and {names[-1]}"

def _sentence(student: Student, days: List[date]) -> str:
    count = len(days)
    noun = "day" if count == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    dates = _join_dates(days)
    return f"{name} was absent {count} {noun}: {dates}."

# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice for a parent listing each absent day."""
    days = _absent_days(student, list(marks))
    return _sentence(student, days)
